## What's actually broken

| # | Defect | Why preview crashes / misbehaves |
|---|---|---|
| 1 | `async function getBucketUrl(arn)` + `await arn` | `Output<T>` is *thenable-ish* only in the sense that `await` on it works in some versions but **resolves to `undefined` during preview** (unknown values). The exported value is a `Promise<string>`, so Pulumi serializes a dangling promise — dependency tracking is lost and preview reports "unhandled/unresolved promise". |
| 2 | `pulumi.output("plain-text-password")` | Wraps a literal in an `Output` for no reason, and — worse — it's **not secret**, so the password lands in plaintext in the state file and in `pulumi stack output`. Violates AC #3. |
| 3 | `deletionProtection: false`, `skipFinalSnapshot: true`, no backups, no encryption | Violates AC #2. |
| 4 | Bucket has no SSE, no public-access block | Violates AC #1. |
| 5 | Hardcoded `db.t3.medium` regardless of env | Violates AC #5 / env isolation. |

**Rule of thumb:** never `await` an `Output`. Use `.apply()` for one, `pulumi.all([...]).apply()` for many, or `pulumi.interpolate` for string building. Only use `pulumi.output()` on a value that is a raw promise or a plain value you must *lift* into the Output world — never on a literal you already control.

---

## Fixed `index.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as awsx from "@pulumi/awsx";
import * as eks from "@pulumi/eks";

const config = new pulumi.Config();
const stack = pulumi.getStack();               // "dev" | "prod"
const isProd = stack === "prod";

const region = config.require("region");
const nodeCount = config.requireNumber("nodeCount");
const nodeInstanceType = config.require("nodeInstanceType");
const dbInstanceClass = config.require("dbInstanceClass");
const certificateArn = config.require("certificateArn");

// FIX 2: secret comes from encrypted stack config, never a literal.
// config.requireSecret() already returns Output<string> — do NOT wrap it.
const dbPassword = config.requireSecret("dbPassword");

const tags = { Environment: stack, Project: "myapp", ManagedBy: "pulumi" };

const provider = new aws.Provider("aws", { region: region as aws.Region });
const opts = { provider };

// ---------------------------------------------------------------- S3
const bucket = new aws.s3.BucketV2("app-bucket", {
    bucket: `myapp-assets-${stack}`,
    tags,
}, opts);

new aws.s3.BucketVersioningV2("app-bucket-versioning", {
    bucket: bucket.id,
    versioningConfiguration: { status: "Enabled" },
}, opts);

new aws.s3.BucketServerSideEncryptionConfigurationV2("app-bucket-sse", {
    bucket: bucket.id,
    rules: [{
        applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
        bucketKeyEnabled: true,
    }],
}, opts);

new aws.s3.BucketPublicAccessBlock("app-bucket-pab", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
}, opts);

// FIX 1: no async, no await. Build the URL inside the Output graph.
// pulumi.interpolate keeps the dependency edge and preview-safe unknowns.
const bucketUrl = pulumi.interpolate`https://s3.${region}.amazonaws.com/${bucket.bucket}`;

// If you genuinely need multi-value logic, use .apply / pulumi.all:
//   const bucketUrl = pulumi.all([bucket.bucket, bucket.region])
//       .apply(([name, r]) => `https://s3.${r}.amazonaws.com/${name}`);

// Prod-only cross-region replication -----------------------------------
if (isProd) {
    const replicaProvider = new aws.Provider("aws-replica", { region: "us-west-2" });

    const replicaBucket = new aws.s3.BucketV2("app-bucket-replica", {
        bucket: `myapp-assets-${stack}-replica`,
        tags,
    }, { provider: replicaProvider });

    new aws.s3.BucketVersioningV2("app-bucket-replica-versioning", {
        bucket: replicaBucket.id,
        versioningConfiguration: { status: "Enabled" },
    }, { provider: replicaProvider });

    new aws.s3.BucketServerSideEncryptionConfigurationV2("app-bucket-replica-sse", {
        bucket: replicaBucket.id,
        rules: [{ applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" } }],
    }, { provider: replicaProvider });

    const replRole = new aws.iam.Role("s3-replication-role", {
        assumeRolePolicy: JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
                Effect: "Allow",
                Principal: { Service: "s3.amazonaws.com" },
                Action: "sts:AssumeRole",
            }],
        }),
        tags,
    }, opts);

    // Least privilege, scoped to exactly these two buckets.
    new aws.iam.RolePolicy("s3-replication-policy", {
        role: replRole.id,
        policy: pulumi.all([bucket.arn, replicaBucket.arn]).apply(([src, dst]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Effect: "Allow",
                        Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                        Resource: [src],
                    },
                    {
                        Effect: "Allow",
                        Action: [
                            "s3:GetObjectVersionForReplication",
                            "s3:GetObjectVersionAcl",
                            "s3:GetObjectVersionTagging",
                        ],
                        Resource: [`${src}/*`],
                    },
                    {
                        Effect: "Allow",
                        Action: [
                            "s3:ReplicateObject",
                            "s3:ReplicateDelete",
                            "s3:ReplicateTags",
                        ],
                        Resource: [`${dst}/*`],
                    },
                ],
            })),
    }, opts);

    new aws.s3.BucketReplicationConfig("app-bucket-replication", {
        role: replRole.arn,
        bucket: bucket.id,
        rules: [{
            id: "replicate-all",
            status: "Enabled",
            filter: {},
            deleteMarkerReplication: { status: "Enabled" },
            destination: { bucket: replicaBucket.arn, storageClass: "STANDARD" },
        }],
    }, opts);
}

// ---------------------------------------------------------------- Network
const vpc = new awsx.ec2.Vpc("app-vpc", {
    numberOfAvailabilityZones: isProd ? 3 : 2,
    natGateways: { strategy: isProd ? "OnePerAz" : "Single" },
    tags,
}, opts);

// ---------------------------------------------------------------- RDS
const dbSubnets = new aws.rds.SubnetGroup("app-db-subnets", {
    subnetIds: vpc.privateSubnetIds,
    tags,
}, opts);

const dbSg = new aws.ec2.SecurityGroup("app-db-sg", {
    vpcId: vpc.vpcId,
    description: "Postgres access from within the VPC only",
    ingress: [{
        protocol: "tcp",
        fromPort: 5432,
        toPort: 5432,
        cidrBlocks: [vpc.vpc.cidrBlock],
    }],
    egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
    tags,
}, opts);

const db = new aws.rds.Instance("app-db", {
    engine: "postgres",
    engineVersion: "16.1",
    instanceClass: dbInstanceClass,
    allocatedStorage: isProd ? 100 : 20,
    dbName: "appdb",
    username: "appuser",
    password: dbPassword,                 // Output<string>, already secret
    dbSubnetGroupName: dbSubnets.name,
    vpcSecurityGroupIds: [dbSg.id],

    multiAz: isProd,
    storageEncrypted: true,               // AC #2
    publiclyAccessible: false,            // AC #2
    deletionProtection: true,             // AC #2
    backupRetentionPeriod: isProd ? 30 : 7,
    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `appdb-${stack}-final`,
    applyImmediately: !isProd,
    tags,
}, opts);

// Connection string is derived from a secret -> stays secret automatically.
const dbConnectionString = pulumi.interpolate`postgresql://appuser:${dbPassword}@${db.endpoint}/appdb`;

// ---------------------------------------------------------------- EKS
const cluster = new eks.Cluster("app-cluster", {
    name: `myapp-${stack}`,
    vpcId: vpc.vpcId,
    publicSubnetIds: vpc.publicSubnetIds,
    privateSubnetIds: vpc.privateSubnetIds,
    nodeAssociatePublicIpAddress: false,
    skipDefaultNodeGroup: true,
    createOidcProvider: true,
    tags,
}, opts);

const ngRole = new aws.iam.Role("ng-role", {
    assumeRolePolicy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Principal: { Service: "ec2.amazonaws.com" },
            Action: "sts:AssumeRole",
        }],
    }),
    tags,
}, opts);

[
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
].forEach((arn, i) =>
    new aws.iam.RolePolicyAttachment(`ng-role-attach-${i}`, {
        role: ngRole.name,
        policyArn: arn,
    }, opts));

new eks.ManagedNodeGroup("app-nodes", {
    cluster,
    nodeRole: ngRole,
    instanceTypes: [nodeInstanceType],
    scalingConfig: { desiredSize: nodeCount, minSize: nodeCount, maxSize: nodeCount * 2 },
    subnetIds: vpc.privateSubnetIds,
    tags,
}, opts);

// ---------------------------------------------------------------- Service identity
// Dev: programmatic IAM user. Prod: OIDC-trusted role, no long-lived keys.
let serviceIdentityArn: pulumi.Output<string>;

if (isProd) {
    const oidcArn = cluster.core.oidcProvider!.arn;
    const oidcUrl = cluster.core.oidcProvider!.url;

    const svcRole = new aws.iam.Role("app-service-role", {
        assumeRolePolicy: pulumi.all([oidcArn, oidcUrl]).apply(([arn, url]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Federated: arn },
                    Action: "sts:AssumeRoleWithWebIdentity",
                    Condition: {
                        StringEquals: {
                            [`${url}:sub`]: "system:serviceaccount:default:myapp",
                            [`${url}:aud`]: "sts.amazonaws.com",
                        },
                    },
                }],
            })),
        tags,
    }, opts);

    // AC #4: explicit actions, explicit resources. No wildcards on prod.
    new aws.iam.RolePolicy("app-service-policy", {
        role: svcRole.id,
        policy: bucket.arn.apply(arn => JSON.stringify({
            Version: "2012-10-17",
            Statement: [
                { Effect: "Allow", Action: ["s3:ListBucket"], Resource: [arn] },
                {
                    Effect: "Allow",
                    Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                    Resource: [`${arn}/*`],
                },
            ],
        })),
    }, opts);

    serviceIdentityArn = svcRole.arn;
} else {
    const svcUser = new aws.iam.User("app-service-user", {
        name: `myapp-${stack}-svc`,
        tags,
    }, opts);

    new aws.iam.UserPolicy("app-service-user-policy", {
        user: svcUser.name,
        policy: bucket.arn.apply(arn => JSON.stringify({
            Version: "2012-10-17",
            Statement: [
                { Effect: "Allow", Action: ["s3:ListBucket"], Resource: [arn] },
                {
                    Effect: "Allow",
                    Action: ["s3:GetObject", "s3:PutObject"],
                    Resource: [`${arn}/*`],
                },
            ],
        })),
    }, opts);

    serviceIdentityArn = svcUser.arn;
}

// ---------------------------------------------------------------- HTTPS (ALB :443)
const albSg = new aws.ec2.SecurityGroup("app-alb-sg", {
    vpcId: vpc.vpcId,
    ingress: [{ protocol: "tcp", fromPort: 443, toPort: 443, cidrBlocks: ["0.0.0.0/0"] }],
    egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
    tags,
}, opts);

const alb = new aws.lb.LoadBalancer("app-alb", {
    loadBalancerType: "application",
    internal: !isProd,                       // dev = internal ALB
    securityGroups: [albSg.id],
    subnets: isProd ? vpc.publicSubnetIds : vpc.privateSubnetIds,
    tags,
}, opts);

const tg = new aws.lb.TargetGroup("app-tg", {
    port: 8080,
    protocol: "HTTP",
    targetType: "ip",
    vpcId: vpc.vpcId,
    healthCheck: { path: "/healthz", matcher: "200" },
    tags,
}, opts);

// AC #6: 443 listener with a real cert, no forced 80->443 redirect listener.
new aws.lb.Listener("app-https", {
    loadBalancerArn: alb.arn,
    port: 443,
    protocol: "HTTPS",
    sslPolicy: "ELBSecurityPolicy-TLS13-1-2-2021-06",
    certificateArn,
    defaultActions: [{ type: "forward", targetGroupArn: tg.arn }],
}, opts);

// ---------------------------------------------------------------- Outputs
export const bucketName = bucket.bucket;
export const bucketEndpoint = bucketUrl;            // Output<string>, not a Promise
export const dbEndpoint = db.endpoint;
export const dbConnection = pulumi.secret(dbConnectionString);
export const kubeconfig = pulumi.secret(cluster.kubeconfig);
export const albDnsName = alb.dnsName;
export const serviceIdentity = serviceIdentityArn;
```

---

## Stack configs

`Pulumi.dev.yaml`
```yaml
config:
  aws:region: us-east-1
  myapp:region: us-east-1
  myapp:nodeCount: "2"
  myapp:nodeInstanceType: t3.medium
  myapp:dbInstanceClass: db.t3.micro
  myapp:certificateArn: arn:aws:acm:us-east-1:111122223333:certificate/dev-xxxx
  myapp:dbPassword:
    secure: AAABAK1...   # written by `pulumi config set --secret`
```

`Pulumi.prod.yaml`
```yaml
config:
  aws:region: us-east-1
  myapp:region: us-east-1
  myapp:nodeCount: "4"
  myapp:nodeInstanceType: t3.large
  myapp:dbInstanceClass: db.t3.medium
  myapp:certificateArn: arn:aws:acm:us-east-1:111122223333:certificate/prod-xxxx
  myapp:dbPassword:
    secure: AAABAJ9...
```

Set secrets with:
```bash
pulumi config set --secret --stack prod myapp:dbPassword '<value>'
```
The `secure:` ciphertext is what's committed — plaintext never enters Git (AC #3). Separate stacks give separate state files, so `pulumi up --stack prod` cannot touch dev (AC #7).

---

## The two rules to internalize

1. **`Output` is not a `Promise`.** `await`-ing one throws away preview's unknown-value semantics and drops the resource dependency edge. Stay inside the Output graph: `.apply()`, `pulumi.all([...]).apply()`, `pulumi.interpolate`.
2. **`pulumi.output()` is a lift, not a cast.** Use it only to promote a raw value/promise *into* the Output world when an API demands `Input<T>` and you have a `Promise<T>`. Wrapping a string literal is a no-op that hides the real problem — here, that the secret was hardcoded instead of `config.requireSecret()`.
